   result=subprocess.run([str(out/'focused'),str(case)],env=env,capture_output=True,text=True,timeout=30);(out/(str(case)+'.log')).write_text(result.stdout+result.stderr);row={'variant':variant,'case':case,'exit':result.returncode,'stdout':result.stdout,'log_sha256':sha(out/(str(case)+'.log'))};s['focused'].append(row);save();assert result.returncode==0,row
