  units=[x for x in c['compiled_units'] if x!=c['old_adapter']];source=c['compile'][c['compile'].index('-c')+1];obj=c['compile'][c['compile'].index('-o')+1];units.append({'file':source,'source_sha256':sha(source),'object':obj,'object_sha256':sha(obj),'command':c['compile'],'directory':c['old_adapter']['directory']})
  receipt={'status':'built','executable':str(out/'viewer'),'executable_sha256':sha(out/'viewer'),'inputs_before':c['inputs'],'inputs_after':c['inputs'],'compiled_units':units,'command':c['link'],'linked_unchanged':c['linked_unchanged'],'gfx_sha256':sha(out/'libgfx.a'),'original_receipt':c['original_receipt'],'original_receipt_sha256':c['original_receipt_sha256'],'disclosure':'Only debug adapter regenerated/compiled. Original C/CPU objects and Rust archives are unchanged and hash checked; not PR06 clean builds.'};(out/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(c['cell'],'adapter compiled/relinked',flush=True)
